/**
 * One-time migration for category taxonomy restructuring.
 * Re-matches transactions/favorites/loops from old "coffee_snacks" category
 * to new taxonomy (beverages, desserts_sweets, or snacks_bakery).
 * Preserves user-confirmed category overrides unless their category key no longer exists.
 * Returns migration stats for logging/verification.
 */
export function migrateCategoriesToV2(state: BalanceState): {
  state: BalanceState;
  stats: { transactionsMigrated: number; favoritesUpdated: number; loopsMigrated: number };
} {
  let transactionsMigrated = 0;
  let favoritesUpdated = 0;
  let loopsMigrated = 0;

  // Migrate transactions
  const migratedTransactions = state.transactions.map((tx) => {
    // Check if this transaction's category key still exists
    const catExists = CATEGORIES.some((c) => c.key === tx.category);
    if (!catExists) {
      // Category no longer exists — re-match
      const matched = matchCategory(tx.title, {
        direction: tx.direction,
        overrides: state.categorizationOverrides,
      });
      transactionsMigrated++;
      return { ...tx, category: matched.key, icon: matched.icon };
    }

    // For transactions in the old "coffee_snacks" category (which still exists but may need redistribution),
    // only re-match if there's NO user override for this transaction's title.
    if (tx.category === "coffee_snacks") {
      const titleNorm = normalize(tx.title);
      const hasUserOverride = state.categorizationOverrides[titleNorm] === "coffee_snacks";

      if (!hasUserOverride) {
        // No explicit user choice for this coffee_snacks entry — let it re-match
        const matched = matchCategory(tx.title, {
          direction: tx.direction,
          overrides: state.categorizationOverrides,
        });
        // Only migrate if the match changed the category
        if (matched.key !== "coffee_snacks") {
          transactionsMigrated++;
          return { ...tx, category: matched.key, icon: matched.icon };
        }
      }
    }

    return tx;
  });

  // Migrate favorites
  const migratedFavorites = state.favorites.map((fav) => {
    const catExists = CATEGORIES.some((c) => c.key === fav.category);
    if (!catExists) {
      // Category key no longer exists — pick a sensible default for this favorite
      const matched = matchCategory(fav.label, { direction: fav.direction ?? "out" });
      favoritesUpdated++;
      return { ...fav, category: matched.key, icon: matched.icon };
    }
    return fav;
  });

  // Migrate loops
  const migratedLoops = state.loops.map((loop) => {
    const catExists = CATEGORIES.some((c) => c.key === loop.category);
    if (!catExists) {
      // Category key no longer exists — re-match
      const matched = matchCategory(loop.label, { direction: loop.direction });
      loopsMigrated++;
      return { ...loop, category: matched.key, icon: matched.icon };
    }
    return loop;
  });

  return {
    state: {
      ...state,
      transactions: migratedTransactions,
      favorites: migratedFavorites,
      loops: migratedLoops,
    },
    stats: { transactionsMigrated, favoritesUpdated, loopsMigrated },
  };
}

