// Handle Android back button and iOS swipe-back to return to Home
useEffect(() => {
  const handleBackButton = async () => {
    // Close any open modals first
    if (favEditOpen || loopEditOpen || customOpen || photoViewerOpen || confirmRemovePhoto || confirmReset || confirmLogout) {
      setFavEditOpen(false);
      setLoopEditOpen(false);
      setCustomOpen(false);
      setPhotoViewerOpen(false);
      setConfirmRemovePhoto(false);
