import {
  THEME_META, colorFor, loadTheme, saveTheme, type ThemeState, type ThemeId,
} from "@/lib/themes";
import { clearAvatar, initials, loadAvatar, saveAvatar } from "@/lib/avatar";
import { NOTHING_YELLOW } from "@/components/YellowArrow";
