    singleStep?: boolean;
  } | null;
  currentBalance: number;
  overrides: Record<string, string>;
  onLearnCategory: (text: string, key: string) => void;
  sheetTopPx?: number;
}

const SPRING = { type: "spring" as const, stiffness: 220, damping: 28, mass: 0.9 };
const DEFAULT_SHEET_TOP_PX = 96;

type Mode = "normal" | "lend" | "items";

export function AddTransactionModal({
  open, onClose, onSave, direction, editing, prefill, currentBalance,
  overrides, onLearnCategory, sheetTopPx,
}: Props) {
  useOverlayState(open);
  const SHEET_TOP_PX = Math.max(88, sheetTopPx ?? DEFAULT_SHEET_TOP_PX);
  const isIncome = direction === "in";
  const [step, setStep] = useState(1);
  const [mode, setMode] = useState<Mode>("normal");
  const [title, setTitle] = useState("");
  const [note, setNote] = useState("");
  const [noteOpen, setNoteOpen] = useState(false);
  const [lentTo, setLentTo] = useState("");
  const [items] = useState<LineItem[]>([]);
  const [itemsHaveAmounts] = useState(false);
  const [category, setCategory] = useState(
    isIncome ? PICKABLE_INCOME_CATEGORIES[0].key : PICKABLE_EXPENSE_CATEGORIES[0].key,
  );
  const [icon, setIcon] = useState(
    isIncome ? PICKABLE_INCOME_CATEGORIES[0].icon : PICKABLE_EXPENSE_CATEGORIES[0].icon,
  );
  const [autoCat, setAutoCat] = useState(true);
  const [showAutoCatBadge, setShowAutoCatBadge] = useState(false);
  const [amount, setAmount] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>("cash");
  const [catPickerOpen, setCatPickerOpen] = useState(false);
  const [singleStep, setSingleStep] = useState(false);

  // Step-2 inline editing
  const [editingTitle, setEditingTitle] = useState(false);
  const [editingNote, setEditingNote] = useState(false);

  // Input refs for conditional focus (avoid unconditional autoFocus on unmounted steps)
  const titleInputRef = useRef<HTMLInputElement>(null);
  const lentToInputRef = useRef<HTMLInputElement>(null);
  const editingTitleInputRef = useRef<HTMLInputElement>(null);
  const editingNoteTextareaRef = useRef<HTMLTextAreaElement>(null);

  const kb = useKeyboardOffset();
  useBodyScrollLock(open);


  // Reset on open/close
  useEffect(() => {
    if (!open) {
      setStep(1); setMode("normal"); setTitle(""); setNote(""); setNoteOpen(false);
      setLentTo("");
      const initialCat = isIncome ? PICKABLE_INCOME_CATEGORIES[0] : PICKABLE_EXPENSE_CATEGORIES[0];
      setCategory(initialCat.key); setIcon(initialCat.icon);
      setAutoCat(true); setShowAutoCatBadge(false); setAmount(""); setPaymentMethod("cash");
      setCatPickerOpen(false); setSingleStep(false);
      setEditingTitle(false); setEditingNote(false);
      return;
    }
    if (editing) {
      setTitle(editing.title);
      setNote(editing.note ?? "");
      setNoteOpen(!!editing.note);
      setCategory(editing.category);
      setIcon(editing.icon);
      setAmount(String(editing.amount));
      setPaymentMethod(editing.paymentMethod);
      setAutoCat(false);
      if (editing.lentTo) { setMode("lend"); setLentTo(editing.lentTo); }
      else if (editing.items && editing.items.length > 0) { setMode("items"); }
      setStep(editing.lentTo ? 3 : 2);
    } else if (prefill) {
      if (prefill.title) setTitle(prefill.title);
      if (prefill.category) { setCategory(prefill.category); setAutoCat(false); }
      if (prefill.icon) setIcon(prefill.icon);
      if (prefill.paymentMethod) setPaymentMethod(prefill.paymentMethod);
      if (prefill.step) setStep(prefill.step as 1 | 2 | 3);
      if (prefill.singleStep) setSingleStep(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  // Conditional focus: only focus when the step is actually being displayed (not transitioning through)
  useEffect(() => {
    if (!open) return;
    
    // Small delay to ensure the step has actually rendered and the modal is visible
    const focusTimer = setTimeout(() => {
      if (step === 1 && titleInputRef.current && !editingTitle) {
        titleInputRef.current.focus();
      } else if (step === 2 && mode === "lend" && lentToInputRef.current) {
        lentToInputRef.current.focus();
      }
      // Don't auto-focus on finalStep (step 3) — that step has a keypad, not a text input
    }, 50);

    return () => clearTimeout(focusTimer);
  }, [open, step, mode, editingTitle]);

  // Focus when inline editing mode is activated (on final step)
  const stepsTotal = mode === "lend" ? 3 : 2;
  const finalStep = stepsTotal;

  useEffect(() => {
    if (!open || step !== finalStep) return;
    
    const focusTimer = setTimeout(() => {
      if (editingTitle && editingTitleInputRef.current) {
        editingTitleInputRef.current.focus();
      } else if (editingNote && editingNoteTextareaRef.current) {
        editingNoteTextareaRef.current.focus();
      }
    }, 50);

    return () => clearTimeout(focusTimer);
  }, [open, step, editingTitle, editingNote, finalStep]);

  // Auto-category from description
  const matched = useMemo(
    () => matchCategory(title, { overrides, direction }),
    [title, overrides, direction],
  );
  useEffect(() => {
    if (!autoCat || !title.trim()) {
      setShowAutoCatBadge(false);
      return;
    }
    setCategory(matched.key);
    setIcon(matched.icon);
    if (title.trim().length > 2 && matched.key !== "misc") {
      setShowAutoCatBadge(true);
      const timer = setTimeout(() => setShowAutoCatBadge(false), 1800);
      return () => clearTimeout(timer);
    }
    setShowAutoCatBadge(false);
  }, [matched, autoCat, title]);


  const amountForReview = parseFloat(amount || "0");

  const pressKey = (k: string) => {
    haptic("tick");
    if (k === "back") setAmount((a) => a.slice(0, -1));
    else if (k === ".") {
      if (!amount.includes(".")) setAmount((a) => (a === "" ? "0." : a + "."));
    } else setAmount((a) => (a === "0" ? k : a + k));
  };

  const canAdvance = (() => {
    if (step === 1) return title.trim().length > 0;
    if (step === 2 && mode === "lend") return lentTo.trim().length > 0;
    return true;
  })();

  const next = () => {
    if (!canAdvance) return;
    haptic("tick");
    setStep((s) => (s + 1) as 1 | 2 | 3);
  };
  const back = () => { haptic("tick"); setStep((s) => Math.max(1, s - 1) as 1 | 2 | 3); };

  const finalAmount = amountForReview;
  const canSave =
    finalAmount > 0 &&
    title.trim().length > 0 &&
    (mode !== "lend" || lentTo.trim().length > 0);

  const overdraft = !isIncome
    ? Math.max(
        0,
        finalAmount -
          (currentBalance + (editing && editing.direction === "out" ? editing.amount : 0)),
      )
    : 0;
  const alreadyNegative = currentBalance < 0;

  const commit = () => {
    if (!canSave) return;
    const amt = finalAmount;
    if (!autoCat && title.trim() && mode !== "lend") {
      onLearnCategory(title, category);
    }
    const finalCategory = mode === "lend" ? LENT_OUT_KEY : category;
    const finalIcon = mode === "lend" ? "Handshake" : icon;
    const finalItems: LineItem[] | null = mode === "items" ? items : null;

    onSave({
      id: editing?.id,
      timestamp: editing?.timestamp,
      title: title.trim(),
      note: note.trim() || null,
      amount: amt,
      category: finalCategory,
      icon: finalIcon,
      direction,
      paymentMethod,
      lentTo: mode === "lend" ? lentTo.trim() : null,
      repaid: editing?.repaid ?? (mode === "lend" ? false : null),
      items: finalItems,
      sourceLoopId: editing?.sourceLoopId ?? null,
    });
    haptic("success");
    onClose();
  };

  const accent = isIncome ? "#10B981" : "#F87171";
  const sign = isIncome ? "+" : "−";
  const cat = getCategory(category);
  const catPool = isIncome ? PICKABLE_INCOME_CATEGORIES : PICKABLE_EXPENSE_CATEGORIES;

  const node = (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            className="fixed inset-0 z-40 bg-transparent"
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.div
            layoutId="fab"
            className="fixed inset-x-0 bottom-0 z-50 mx-auto max-h-[85vh] w-full max-w-md overflow-hidden overflow-x-hidden overflow-y-auto rounded-t-[28px] border-t border-white/10 bg-black"
            style={{ top: SHEET_TOP_PX, bottom: 0 }}
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: "100%", opacity: 0 }}
            transition={{ type: "spring", stiffness: 400, damping: 32, mass: 0.9 }}
            drag="y"
            dragConstraints={{ top: 0, bottom: 0 }}
            dragElastic={{ top: 0, bottom: 0.25 }}
            dragMomentum={false}
            onDragEnd={(event, info) => {
              if (info.offset.y > 100 || info.velocity.y > 500) {
                onClose();
              }
            }}
          >
            {/* Grey drag handle */}
            <div className="flex justify-center pt-3">
              <div className="h-1.5 w-12 rounded-full bg-white/20" />
            </div>
            <button
              onClick={onClose}
              className="absolute right-4 top-3 z-10 rounded-full p-2 text-muted-foreground"
              aria-label="Close"
            >
              <X size={18} strokeWidth={1.5} />
            </button>

            <div className="relative h-[calc(100%-1.25rem)] w-full">
              <AnimatePresence initial={false} mode="popLayout">
                {step === 1 && (
                  <motion.div
                    key="step1"
                    initial={{ x: "-100%", opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    exit={{ x: "-100%", opacity: 0 }}
                    transition={SPRING}
                    className="absolute inset-0 mx-auto flex max-w-md flex-col px-6 pt-6"
                  >
                    <p className="text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                      Step 1 of {stepsTotal} · {isIncome ? "Income" : "Expense"}
                    </p>
                    <h2 className="mt-3 text-2xl font-light leading-tight">
                      What's this for?
                    </h2>
                    <input
                      ref={titleInputRef}
                      value={title}
                      onChange={(e) => { setTitle(e.target.value); setAutoCat(true); }}
                      placeholder={isIncome ? "e.g. Pocket money from mom" : "e.g. Cafeteria samosa"}
                      onKeyDown={(e) => { if (e.key === "Enter") next(); }}
                      className="mt-6 w-full border-b border-white/15 bg-transparent pb-3 text-2xl font-light outline-none placeholder:text-muted-foreground/40 focus:border-white/40"
                    />

                    {/* Two modifier buttons */}
                    <div className="mt-5 flex gap-2">
                      <button
                        onClick={() => setNoteOpen((v) => !v)}
                        className={`flex flex-1 items-center justify-center gap-2 rounded-full border px-3 py-2 text-xs ${
                          noteOpen ? "border-white/30 text-foreground" : "border-white/10 text-muted-foreground"
                        }`}
                      >
                        <FileText size={13} strokeWidth={1.6} />
                        Add a note
                      </button>
                      {!isIncome && (
                        <button
                          onClick={() => setMode((m) => (m === "lend" ? "normal" : "lend"))}
                          className={`flex flex-1 items-center justify-center gap-2 rounded-full border px-3 py-2 text-xs ${
                            mode === "lend" ? "border-amber-400/50 text-amber-300" : "border-white/10 text-muted-foreground"
                          }`}
                        >
                          <Handshake size={13} strokeWidth={1.6} />
                          I lent this to someone
                        </button>
                      )}
                    </div>

                    {noteOpen && (
                      <motion.textarea
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        value={note}
                        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setNote(e.target.value)}
                        placeholder="Optional notes…"
                        className="mt-2 w-full resize-none rounded-2xl border border-white/10 bg-transparent p-3 text-sm outline-none placeholder:text-muted-foreground/40"
                        rows={2}
                      />
                    )}

                    <div className="flex-1" />

                    <div
                      className="pb-5 transition-[padding] duration-150"
                      style={{ paddingBottom: kb ? kb + 12 : 20 }}
                    >
                      <YellowArrowButton onClick={next} disabled={!canAdvance} />
                    </div>
                  </motion.div>
                )}

                {step === 2 && mode === "lend" && (
                  <motion.div
                    key="step2-lend"
                    initial={{ x: "100%", opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    exit={{ x: "100%", opacity: 0 }}
                    transition={SPRING}
                    className="absolute inset-0 mx-auto flex max-w-md flex-col px-6 pt-6"
                  >
                    <button onClick={back} className="self-start rounded-full p-2 text-muted-foreground" aria-label="Back">
                      <ArrowLeft size={20} strokeWidth={1.5} />
                    </button>
                    <p className="mt-2 text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                      Step 2 of 3 · Lend
                    </p>
                    <h2 className="mt-3 text-2xl font-light leading-tight">Who's this for?</h2>
                    <input
                      ref={lentToInputRef}
                      value={lentTo}
                      onChange={(e) => setLentTo(e.target.value)}
                      placeholder="e.g. Rohan"
                      onKeyDown={(e) => { if (e.key === "Enter") next(); }}
                      className="mt-6 w-full border-b border-white/15 bg-transparent pb-3 text-2xl font-light outline-none placeholder:text-muted-foreground/40"
                    />
                    <div className="flex-1" />
                    <div
                      className="pb-5 transition-[padding] duration-150"
                      style={{ paddingBottom: kb ? kb + 12 : 20 }}
                    >
                      <YellowArrowButton onClick={next} disabled={!canAdvance} />
                    </div>
                  </motion.div>
                )}

                {step === finalStep && (
                  <motion.div
                    key="step-final"
                    initial={{ x: "100%", opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    exit={{ x: "100%", opacity: 0 }}
                    transition={SPRING}
                    className="absolute inset-0 mx-auto flex max-w-md flex-col px-6 pt-5 pb-5"
                  >
                    {!singleStep ? (
                      <button onClick={back} className="self-start rounded-full p-2 text-muted-foreground" aria-label="Back">
                        <ArrowLeft size={20} strokeWidth={1.5} />
                      </button>
                    ) : (
                      <div className="h-9" />
                    )}

                    {singleStep ? (
                      <p className="mt-1 text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                        Add money · {PAYMENT_METHODS.find((m) => m.key === paymentMethod)?.label}
                      </p>
                    ) : (
                      <p className="mt-1 text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                        {mode === "lend" ? "Lend" : (isIncome ? "Income" : "Expense")}
                      </p>
                    )}

                    {/* Editable title */}
                    {!singleStep && (
                      <div className="mt-1">
                        {editingTitle ? (
                          <input
                            ref={editingTitleInputRef}
                            value={title}
                            onChange={(e) => { setTitle(e.target.value); setAutoCat(true); }}
                            onBlur={() => setEditingTitle(false)}
                            onKeyDown={(e) => { if (e.key === "Enter") setEditingTitle(false); }}
                            className="w-full bg-transparent text-xl font-medium outline-none border-b border-white/20"
                            autoFocus
                          />
                        ) : (
                          <button
                            onClick={() => setEditingTitle(true)}
                            className="block w-full truncate text-left text-xl font-medium"
                          >
                            {mode === "lend" ? `Lent to ${lentTo}` : (title || "Untitled")}
                          </button>
                        )}
                      </div>
                    )}

                    {/* category chip */}
                    {mode !== "lend" && !singleStep && (
                      <>
                        <div className="mt-2 flex w-fit items-center gap-2 min-h-[44px]">
                          <button
                            onClick={() => setCatPickerOpen((v) => !v)}
                            className={`flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs ${showAutoCatBadge ? "category-border-magic" : ""}`}
                            style={{
                              borderColor: cat.color + "55",
                              background: `color-mix(in oklab, ${cat.color} 14%, transparent)`,
                              color: cat.color,
                            }}
                          >
                            <Icon name={cat.icon} size={12} strokeWidth={1.7} />
                            <span className="font-medium">{cat.label}</span>
                          </button>
                          <div className="min-w-[132px] min-h-[20px]">
                            <AnimatePresence mode="wait">
                              {showAutoCatBadge ? (
                                <motion.p
                                  key="autocat"
                                  initial={{ opacity: 0, x: -6 }}
                                  animate={{ opacity: 1, x: 0 }}
                                  exit={{ opacity: 0, x: -6 }}
                                  transition={{ duration: 0.22 }}
                                  className="text-[10px] text-muted-foreground whitespace-nowrap"
                                >
                                  Automatically categorised
                                </motion.p>
                              ) : (
                                <motion.div
                                  key="autocat-placeholder"
                                  initial={{ opacity: 0 }}
                                  animate={{ opacity: 0 }}
                                  exit={{ opacity: 0 }}
                                  className="h-[14px]"
                                />
                              )}
                            </AnimatePresence>
                          </div>
                        </div>

                        <AnimatePresence>
                          {catPickerOpen && (
                            <motion.div
                              initial={{ opacity: 0, height: 0 }}
                              animate={{ opacity: 1, height: "auto" }}
                              exit={{ opacity: 0, height: 0 }}
                              className="-mx-6 mt-2 overflow-hidden"
                            >
                              <CategoryPicker
                                categories={catPool}
                                selectedKey={category}
                                onSelect={(c) => {
                                  setAutoCat(false); setCategory(c.key); setIcon(c.icon);
                                  setCatPickerOpen(false);
                                }}
                              />
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </>
                    )}

                    {/* Editable note (preserves line breaks, no wrap) */}
                    {!singleStep && note && !editingNote && (
                      <button
                        onClick={() => setEditingNote(true)}
                        className="mt-2 block w-full overflow-x-auto whitespace-pre text-left text-xs text-muted-foreground"
                      >
                        {note}
                      </button>
                    )}
                    {!singleStep && editingNote && (
                      <textarea
                        ref={editingNoteTextareaRef}
                        value={note}
                        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setNote(e.target.value)}
                        onBlur={() => setEditingNote(false)}
                        rows={3}
                        className="mt-2 w-full resize-none rounded-xl border border-white/10 bg-transparent p-2 text-xs outline-none"
                        autoFocus
                      />
                    )}

                    {/* Amount display — with stable width to prevent bounce on digit changes */}
                    <div className="mt-4 flex items-baseline justify-center gap-1.5 min-h-[80px]">
                      <span
                        className="font-mono-display text-3xl"
                        style={{ color: accent }}
                      >{sign}</span>
                      <span className="font-mono-display text-3xl text-muted-foreground">₹</span>
                      <motion.span
                        key={amount || "0"}
                        initial={{ scale: 0.85, opacity: 0, y: 8 }}
                        animate={{ scale: 1, opacity: 1, y: 0 }}
                        transition={{ type: "spring", stiffness: 320, damping: 16 }}
                        className="font-mono-display text-6xl font-light leading-none min-w-[140px] text-center"
                      >
                        {amount || "0"}
                      </motion.span>
                    </div>

                    {/* Overdraft warning */}
                    {overdraft > 0 && (
                      <p className="mt-2 text-center text-[11px] text-amber-300/90">
                        Heads up — this will put you {formatCurrency(overdraft)} in the red.
                      </p>
                    )}
                    {overdraft === 0 && alreadyNegative && !isIncome && finalAmount > 0 && (
                      <p className="mt-2 text-center text-[11px] text-rose-400/90">
                        You're already {formatCurrency(Math.abs(currentBalance))} in the red — this adds to it.
                      </p>
                    )}

                    {/* Add-a-note row (singleStep) — moved above payment methods */}
                    {singleStep && (
                      <div className="mt-3 space-y-2 min-h-[44px]">
                        <button
                          onClick={() => setNoteOpen((v) => !v)}
                          className={`flex w-full items-center justify-center gap-2 rounded-full border px-3 py-2 text-xs ${
                            noteOpen ? "border-white/30 text-foreground" : "border-white/10 text-muted-foreground"
                          }`}
                        >
                          <FileText size={13} strokeWidth={1.6} />
                          Add a note
                        </button>
                        {noteOpen && (
                          <motion.textarea
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: "auto" }}
                            value={note}
                            onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setNote(e.target.value)}
                            placeholder="Optional notes…"
                            className="w-full resize-none rounded-2xl border border-white/10 bg-transparent p-3 text-sm outline-none placeholder:text-muted-foreground/40"
                            rows={2}
                          />
                        )}
                      </div>
                    )}

                    {/* Payment method chips — stable height container */}
                    <div className="mt-3 flex flex-wrap justify-center gap-1.5 min-h-[44px]">
                      {PAYMENT_METHODS.map((m) => {
                        const sel = paymentMethod === m.key;
                        return (
                          <button
                            key={m.key}
                            onClick={() => { setPaymentMethod(m.key); haptic("tick"); }}
                            className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[11px] ${
                              sel ? "border-white/40 text-foreground" : "border-white/10 text-muted-foreground"
                            }`}
                          >
                            <Icon name={m.icon} size={11} strokeWidth={1.6} />
                            {m.label}
                          </button>
                        );
                      })}
                    </div>

                    {/* Keypad — fills available vertical space, 4×3 even grid */}
                    <div
                      className="mt-3 grid w-full"
                      style={{
                        flex: 1,
                        minHeight: 0,
                        gridTemplateColumns: "repeat(3, 1fr)",
                        gridTemplateRows: "repeat(4, 1fr)",
                      }}
                    >
                      {["1","2","3","4","5","6","7","8","9",".","0","back"].map((k) => (
                        <motion.button
                          key={k}
                          whileTap={{ scale: 0.85 }}
                          transition={{ type: "spring", stiffness: 500, damping: 16 }}
                          onClick={() => pressKey(k)}
                          className="font-mono-display flex h-full w-full items-center justify-center text-2xl font-light text-foreground/90"
                        >
                          {k === "back" ? <Delete size={18} strokeWidth={1.5} /> : k}
                        </motion.button>
                      ))}
                    </div>

                    <div
                      className="mt-4 transition-[padding] duration-150"
                      style={{ paddingBottom: kb ? kb : 0 }}
                    >
                      <motion.button
                        whileTap={{ scale: 0.97 }}
                        onClick={commit}
                        disabled={!canSave}
                        className="flex w-full items-center justify-center gap-2 rounded-full py-4 text-sm font-semibold uppercase tracking-[0.2em] text-white disabled:opacity-30"
                        style={{ background: isIncome ? "#16A34A" : "#EF4444" }}
                      >
                        {editing ? "Save changes" : isIncome ? "Add money" : "Log expense"}
                      </motion.button>

                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );

  if (typeof document === "undefined") return null;
  return createPortal(node, document.body);
}

import { AnimatePresence, motion } from "framer-motion";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { Delete, X } from "lucide-react";
import { Icon } from "./Icon";
import { CategoryPicker } from "./CategoryPicker";
import { useBodyScrollLock } from "@/hooks/useBodyScrollLock";
import { useKeyboardOffset } from "@/hooks/useKeyboardOffset";
import { useOverlayState } from "@/lib/OverlayContext";
import {
  LENT_OUT_KEY,
  PAYMENT_METHODS,
  PICKABLE_EXPENSE_CATEGORIES,
  PICKABLE_INCOME_CATEGORIES,
  getCategory,
  type PaymentMethod,
  type Transaction,
} from "@/lib/ledger";
import { haptic } from "@/lib/haptics";

interface Props {
  open: boolean;
  tx: Transaction | null;
  onClose: () => void;
  onSave: (tx: Transaction) => void;
  sheetTopPx?: number;
}

const SPRING = { type: "spring" as const, stiffness: 220, damping: 28, mass: 0.9 };
const DEFAULT_SHEET_TOP_PX = 96;

export function EditTransactionPopup({ open, tx, onClose, onSave, sheetTopPx }: Props) {
  useOverlayState(open && !!tx);
  const SHEET_TOP_PX = Math.max(88, sheetTopPx ?? DEFAULT_SHEET_TOP_PX);
  const [title, setTitle] = useState("");
  const [editingTitle, setEditingTitle] = useState(false);
  const [amount, setAmount] = useState("0");
  const [note, setNote] = useState("");
  const [editingNote, setEditingNote] = useState(false);
  const [pm, setPm] = useState<PaymentMethod>("cash");
  const [lentTo, setLentTo] = useState("");
  const [editingLentTo, setEditingLentTo] = useState(false);
  const [isLend, setIsLend] = useState(false);
  const [category, setCategory] = useState<string>("misc");
  const [icon, setIcon] = useState<string>("Sparkles");
  const [catPickerOpen, setCatPickerOpen] = useState(false);
  const kb = useKeyboardOffset();

  useEffect(() => {
    if (!open || !tx) return;
    setTitle(tx.title);
    setAmount(String(tx.amount));
    setNote(tx.note ?? "");
    setPm(tx.paymentMethod);
    setLentTo(tx.lentTo ?? "");
    setIsLend(!!tx.lentTo);
    setCategory(tx.category);
    setIcon(tx.icon);
    setEditingTitle(false);
    setEditingNote(false);
    setEditingLentTo(false);
    setCatPickerOpen(false);
  }, [open, tx]);

  useBodyScrollLock(open);

  // Hardware back closes
  useEffect(() => {
    if (!open) return;
    try { window.history.pushState({ __editSheet: true }, ""); } catch { /* */ }
    const onPop = () => onClose();
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, [open, onClose]);

  if (typeof document === "undefined") return null;
  if (!tx) return null;

  const pressKey = (k: string) => {
    haptic("tick");
    if (k === "back") setAmount((a) => (a.length <= 1 ? "0" : a.slice(0, -1)));
    else if (k === ".") {
      if (!amount.includes(".")) setAmount((a) => (a === "" || a === "0" ? "0." : a + "."));
    } else setAmount((a) => (a === "0" || a === "" ? k : a + k));
  };

  const commit = () => {
    const amt = parseFloat(amount) || 0;
    if (amt <= 0) return;
    if (!title.trim()) return;
    if (isLend && !lentTo.trim()) return;
    onSave({
      ...tx,
      title: title.trim(),
      amount: amt,
      note: note.trim() || null,
      paymentMethod: pm,
      lentTo: isLend ? lentTo.trim() : null,
      category: isLend ? LENT_OUT_KEY : category,
      icon: isLend ? "Handshake" : icon,
      repaid: isLend ? (tx.repaid ?? false) : null,
    });
    haptic("success");
    onClose();
  };

  const accent = tx.direction === "in" ? "#10B981" : "#F87171";
  const sign = tx.direction === "in" ? "+" : "−";
  const cat = isLend ? getCategory(LENT_OUT_KEY) : getCategory(category);
  const catPool = tx.direction === "in" ? PICKABLE_INCOME_CATEGORIES : PICKABLE_EXPENSE_CATEGORIES;

  const node = (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            className="fixed inset-x-0 top-0 z-[120]"
            style={{ height: SHEET_TOP_PX, background: "transparent" }}
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.div
            className="fixed inset-x-0 z-[130] mx-auto w-full max-w-md overflow-hidden overflow-x-hidden rounded-t-[28px] border-t border-white/10 bg-black"
            style={{ top: SHEET_TOP_PX, bottom: 0 }}
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: "100%", opacity: 0 }}
            transition={{ type: "spring", stiffness: 400, damping: 32, mass: 0.9 }}
            drag="y"
            dragConstraints={{ top: 0, bottom: 0 }}
            dragElastic={{ top: 0, bottom: 0.25 }}
            dragMomentum={false}
            onDragEnd={(event, info) => {
              if (info.offset.y > 100 || info.velocity.y > 500) {
                onClose();
              }
            }}
          >
            <div className="flex justify-center pt-3">
              <div className="h-1.5 w-12 rounded-full bg-white/20" />
            </div>
            <button
              onClick={onClose}
              className="absolute right-3 top-3 z-10 grid h-9 w-9 place-items-center rounded-full bg-white/[0.06] text-foreground/90"
              aria-label="Close"
            >
              <X size={18} strokeWidth={1.6} />
            </button>

            <div className="mx-auto flex h-[calc(100%-1.25rem)] max-w-md flex-col px-6 pt-4 pb-5">
              <p className="text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                Edit · {isLend ? "Lend" : (tx.direction === "in" ? "Income" : "Expense")}
              </p>

              {/* Editable title */}
              <div className="mt-1">
                {editingTitle ? (
                  <input
                    autoFocus
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    onBlur={() => setEditingTitle(false)}
                    onKeyDown={(e) => { if (e.key === "Enter") setEditingTitle(false); }}
                    className="w-full border-b border-white/30 bg-transparent text-xl font-medium outline-none"
                  />
                ) : (
                  <button
                    onClick={() => setEditingTitle(true)}
                    className="block w-full truncate text-left text-xl font-medium"
                  >
                    {isLend ? `Lent to ${lentTo || "—"}` : (title || "Untitled")}
                  </button>
                )}
              </div>

              {/* Category chip — opens picker */}
              {!isLend && (
                <>
                  <button
                    onClick={() => setCatPickerOpen((v) => !v)}
                    className="mt-2 flex w-fit items-center gap-2 rounded-full border px-3 py-1.5 text-xs"
                    style={{
                      borderColor: cat.color + "55",
                      background: `color-mix(in oklab, ${cat.color} 14%, transparent)`,
                      color: cat.color,
                    }}
                  >
                    <Icon name={cat.icon} size={12} strokeWidth={1.7} />
                    <span className="font-medium">{cat.label}</span>
                  </button>
                  <AnimatePresence>
                    {catPickerOpen && (
                      <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        className="-mx-6 mt-2 overflow-hidden"
                      >
                        <CategoryPicker
                          categories={catPool}
                          selectedKey={category}
                          onSelect={(c) => {
                            setCategory(c.key); setIcon(c.icon);
                            setCatPickerOpen(false);
                            haptic("tick");
                          }}
                        />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </>
              )}

              {/* Editable note */}
              <div className="mt-3">
                {editingNote ? (
                  <textarea
                    autoFocus
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    onBlur={() => setEditingNote(false)}
                    rows={2}
                    className="w-full resize-none rounded-xl border border-white/10 bg-transparent p-2 text-xs outline-none"
                  />
                ) : (
                  <button
                    onClick={() => setEditingNote(true)}
                    className="block w-full overflow-x-auto whitespace-pre text-left text-xs text-muted-foreground"
                  >
                    {note || <span className="text-muted-foreground/60">+ Add note</span>}
                  </button>
                )}
              </div>

              {/* Amount display */}
              <div className="mt-3 flex items-baseline justify-center gap-1.5">
                <span className="font-mono-display text-3xl" style={{ color: accent }}>{sign}</span>
                <span className="font-mono-display text-3xl text-muted-foreground">₹</span>
                <motion.span
                  key={amount || "0"}
                  initial={{ scale: 0.9, opacity: 0, y: 6 }}
                  animate={{ scale: 1, opacity: 1, y: 0 }}
                  transition={{ type: "spring", stiffness: 320, damping: 16 }}
                  className="font-mono-display text-5xl font-light leading-none"
                >
                  {amount || "0"}
                </motion.span>
              </div>

              {/* Lend controls */}
              {(tx.direction === "out" || isLend) && (
                <div className="mt-3">
                  {isLend ? (
                    <div className="space-y-2">
                      {editingLentTo ? (
                        <input
                          autoFocus
                          value={lentTo}
                          onChange={(e) => setLentTo(e.target.value)}
                          onBlur={() => setEditingLentTo(false)}
                          onKeyDown={(e) => { if (e.key === "Enter") setEditingLentTo(false); }}
                          placeholder="Who?"
                          className="w-full border-b border-white/30 bg-transparent pb-1.5 text-sm outline-none"
                        />
                      ) : (
                        <button
                          onClick={() => setEditingLentTo(true)}
                          className="block w-full border-b border-white/15 pb-1.5 text-left text-sm"
                        >
                          {lentTo
                            ? <>Lent to <span className="text-amber-300">{lentTo}</span></>
                            : <span className="text-muted-foreground">Tap to set who you lent it to</span>}
                        </button>
                      )}
                      <button
                        onClick={() => { setIsLend(false); setLentTo(""); }}
                        className="w-full rounded-full border border-amber-400/40 px-3 py-1.5 text-[10px] uppercase tracking-[0.2em] text-amber-300/90"
                      >
                        Remove lend
                      </button>
                    </div>
                  ) : (
                    <button
                      onClick={() => { setIsLend(true); setEditingLentTo(true); }}
                      className="w-full rounded-full border border-white/10 px-3 py-1.5 text-[10px] uppercase tracking-[0.2em] text-muted-foreground"
                    >
                      Turn into a lend
                    </button>
                  )}
                </div>
              )}

              {/* Payment method chips */}
              <div className="mt-3 flex flex-wrap justify-center gap-1.5">
                {PAYMENT_METHODS.map((m) => {
                  const sel = pm === m.key;
                  return (
                    <button
                      key={m.key}
                      onClick={() => { setPm(m.key); haptic("tick"); }}
                      className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[11px] ${
                        sel ? "border-white/40 text-foreground" : "border-white/10 text-muted-foreground"
                      }`}
                    >
                      <Icon name={m.icon} size={11} strokeWidth={1.6} />
                      {m.label}
                    </button>
                  );
                })}
              </div>

              {/* Custom keypad */}
              <div
                className="mt-3 grid w-full"
                style={{
                  flex: 1,
                  minHeight: 0,
                  gridTemplateColumns: "repeat(3, 1fr)",
                  gridTemplateRows: "repeat(4, 1fr)",
                }}
              >
                {["1","2","3","4","5","6","7","8","9",".","0","back"].map((k) => (
                  <motion.button
                    key={k}
                    whileTap={{ scale: 0.85 }}
                    transition={{ type: "spring", stiffness: 500, damping: 16 }}
                    onClick={() => pressKey(k)}
                    className="font-mono-display flex h-full w-full items-center justify-center text-2xl font-light text-foreground/90"
                  >
                    {k === "back" ? <Delete size={18} strokeWidth={1.5} /> : k}
                  </motion.button>
                ))}
              </div>

              <div
                className="mt-3 transition-[padding] duration-150"
                style={{ paddingBottom: kb ? kb : 0 }}
              >
                <motion.button
                  whileTap={{ scale: 0.97 }}
                  onClick={commit}
                  className="flex w-full items-center justify-center gap-2 rounded-full py-4 text-sm font-semibold uppercase tracking-[0.2em] text-white"
                  style={{ background: "#22C55E" }}
                >
                  Save changes
                </motion.button>
              </div>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );

  // Portal to body so the popup sits above the bottom pill regardless of
  // any transformed ancestor stacking contexts.
  return createPortal(node, document.body);
}

import { AnimatePresence, motion } from "framer-motion";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { Trash2, X, Pencil, Check } from "lucide-react";
import { Icon } from "./Icon";
import { CategoryPicker } from "./CategoryPicker";
import { IconPicker } from "./IconPicker";
import { useBodyScrollLock } from "@/hooks/useBodyScrollLock";
import { useKeyboardOffset } from "@/hooks/useKeyboardOffset";
import { useOverlayState } from "@/lib/OverlayContext";
import { CATEGORIES, PAYMENT_METHODS, type Favorite, type PaymentMethod } from "@/lib/ledger";
import { useCategoryColor } from "@/lib/themes";
import { showInfo } from "@/lib/undo";
import { haptic } from "@/lib/haptics";


interface Props {
  open: boolean;
  onClose: () => void;
  favorites: Favorite[];
  onAdd: (f: Omit<Favorite, "id">) => void;
  onUpdate: (id: string, f: Omit<Favorite, "id">) => void;
  onDelete: (id: string) => void;
  /** "manage" shows the saved list + form; "compact" hides the list (create/edit only). */
  mode?: "manage" | "compact";
  /** When provided in compact mode, the form opens pre-filled to edit this favorite. */
  initialEdit?: Favorite | null;
}

export function FavoriteEditor({
  open, onClose, favorites, onAdd, onUpdate, onDelete,
  mode = "manage", initialEdit = null,
}: Props) {
  useOverlayState(open);
  const [editingId, setEditingId] = useState<string | null>(null);
  const kb = useKeyboardOffset();
  const [label, setLabel] = useState("");
  const [category, setCategory] = useState(CATEGORIES[0].key);
  const [icon, setIcon] = useState("Star");
  const [preset, setPreset] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod | null>(null);
  const [pickerOpen, setPickerOpen] = useState(false);
  const themeColor = useCategoryColor();
  useBodyScrollLock(open);


  const resetForm = () => {
    setEditingId(null);
    setLabel(""); setCategory(CATEGORIES[0].key); setIcon("Star"); setPreset(""); setPaymentMethod(null);
  };

  useEffect(() => {
    if (!open) { resetForm(); return; }
    if (initialEdit) {
      setEditingId(initialEdit.id);
      setLabel(initialEdit.label);
      setCategory(initialEdit.category);
      setIcon(initialEdit.icon || "Star");
      setPreset(initialEdit.presetAmount != null ? String(initialEdit.presetAmount) : "");
      setPaymentMethod(initialEdit.paymentMethod ?? null);
    } else {
      resetForm();
    }
  }, [open, initialEdit]);

  const startEdit = (f: Favorite) => {
    setEditingId(f.id);
    setLabel(f.label);
    setCategory(f.category);
    setIcon(f.icon || "Star");
    setPreset(f.presetAmount != null ? String(f.presetAmount) : "");
    setPaymentMethod(f.paymentMethod ?? null);
  };

  const save = () => {
    if (!label.trim()) return;
    const amt = parseFloat(preset);
    const payload: Omit<Favorite, "id"> = {
      label: label.trim(),
      category,
      icon,
      presetAmount: isNaN(amt) ? null : amt,
      paymentMethod: paymentMethod ?? undefined,
    };
    const wasEdit = !!editingId;
    if (editingId) onUpdate(editingId, payload);
    else onAdd(payload);
    haptic("success");
    resetForm();
    onClose();
    showInfo(wasEdit ? "Favourite updated" : "Favourite added");
  };



  const node = (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            className="fixed inset-0 z-40 bg-black/50"
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.div
            initial={{ y: "100%", opacity: 0 }} animate={{ y: kb ? -kb : 0, opacity: 1 }} exit={{ y: "100%", opacity: 0 }}
            transition={{ type: "spring", stiffness: 400, damping: 32, mass: 0.9 }}
            drag="y"
            dragConstraints={{ top: 0, bottom: 0 }}
            dragElastic={{ top: 0, bottom: 0.5 }}
            dragMomentum={false}
            onDragEnd={(event, info) => {
              if (info.offset.y > 100 || info.velocity.y > 500) {
                onClose();
              }
            }}
            className="fixed inset-x-0 bottom-0 z-50 mx-auto max-h-[92vh] w-full max-w-md overflow-x-hidden overflow-y-auto rounded-t-[32px] border-t border-white/10 bg-black p-5 pb-8"
            style={{
              background: "rgba(15, 15, 15, 0.65)",
              backdropFilter: "blur(10px) saturate(150%)",
              WebkitBackdropFilter: "blur(10px) saturate(150%)",
              borderColor: "rgba(255,255,255,0.08)",
              boxShadow: "inset 0 1px 0 rgba(255,255,255,0.08), 0 -20px 60px -20px rgba(0,0,0,0.8)",
            }}
          >
            <div className="mx-auto mb-4 h-1.5 w-12 rounded-full bg-white/15" />
            <div className="flex items-center justify-between">
              <div>
                <p className="text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                  {mode === "compact" ? (editingId ? "Edit" : "New") : "Manage"}
                </p>
                <h2 className="font-mono-display text-xl text-foreground/95">
                  {mode === "compact" ? "FAVORITE" : "FAVORITES"}
                </h2>
              </div>
              <button onClick={onClose} className="rounded-full p-2 text-muted-foreground">
                <X size={18} strokeWidth={1.5} />
              </button>
            </div>

            {/* Existing list */}
            {mode === "manage" && favorites.length > 0 && (
              <div className="mt-5 space-y-1">
                <p className="mb-2 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">
                  Saved · {favorites.length}
                </p>
                {favorites.map((f) => {
                  const isEditing = editingId === f.id;
                  return (
                    <motion.div
                      layout
                      key={f.id}
                      className={`flex items-center gap-3 rounded-2xl border px-3 py-2.5 transition-colors ${
                        isEditing
                          ? "border-white/20 bg-white/[0.06]"
                          : "border-white/[0.06] bg-white/[0.02]"
                      }`}
                    >
                      <span className="grid h-9 w-9 place-items-center rounded-xl border border-white/[0.08]">
                        <Icon name={f.icon} size={15} strokeWidth={1.5} />
                      </span>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-medium">{f.label}</p>
                        <p className="truncate text-[10px] uppercase tracking-[0.18em] text-muted-foreground">
                          {(CATEGORIES.find((c) => c.key === f.category)?.label) ?? "—"}
                          {f.presetAmount != null && ` · ₹${f.presetAmount}`}
                        </p>
                      </div>
                      <button
                        onClick={() => (isEditing ? resetForm() : startEdit(f))}
                        className="rounded-full p-2 text-muted-foreground active:opacity-60"
                        aria-label={isEditing ? "Cancel" : "Edit"}
                      >
                        {isEditing ? <X size={14} /> : <Pencil size={14} strokeWidth={1.6} />}
                      </button>
                      <button
                        onClick={() => { haptic("thud"); onDelete(f.id); }}
                        className="rounded-full p-2 text-muted-foreground active:opacity-60"
                        aria-label="Delete"
                      >
                        <Trash2 size={14} strokeWidth={1.6} />
                      </button>
                    </motion.div>
                  );
                })}
              </div>
            )}

            {/* Form */}
            <div className="mt-5 rounded-2xl border border-white/[0.06] bg-white/[0.02] p-4">
              <p className="mb-3 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">
                {editingId ? "Editing favorite" : "New favorite"}
              </p>

              <div className="flex items-center gap-3">
                <button
                  onClick={() => setPickerOpen(true)}
                  className="grid h-14 w-14 shrink-0 place-items-center rounded-2xl border border-white/[0.08] bg-white/[0.03]"
                >
                  <Icon name={icon} size={22} strokeWidth={1.5} />
                </button>
                <input
                  value={label}
                  onChange={(e) => setLabel(e.target.value)}
                  placeholder="Label"
                  className="w-full border-b border-white/10 bg-transparent pb-1.5 text-base outline-none placeholder:text-muted-foreground focus:border-foreground/40"
                />
              </div>

              <CategoryPicker
                categories={CATEGORIES.filter((c) => c.key !== "lent_out")}
                selectedKey={category}
                onSelect={(c) => { setCategory(c.key); setIcon(c.icon); }}
              />

              <p className="mt-4 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">
                Preset amount · optional
              </p>
              <div className="mt-2 flex items-center gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2">
                <span className="font-mono-display text-sm text-muted-foreground">₹</span>
                <input
                  type="number"
                  value={preset}
                  onChange={(e) => setPreset(e.target.value)}
                  placeholder="Leave blank to enter every time"
                  className="font-mono-display w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground"
                />
              </div>

              <p className="mt-4 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">
                Payment method · optional
              </p>
              <div className="mt-2 flex flex-wrap gap-1.5">
                <button
                  onClick={() => setPaymentMethod(null)}
                  className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[11px] ${
                    paymentMethod === null ? "border-white/40 text-foreground" : "border-white/10 text-muted-foreground"
                  }`}
                >
                  Ask when tapped
                </button>
                {PAYMENT_METHODS.map((m) => {
                  const sel = paymentMethod === m.key;
                  return (
                    <button
                      key={m.key}
                      onClick={() => setPaymentMethod(m.key)}
                      className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[11px] ${
                        sel ? "border-white/40 text-foreground" : "border-white/10 text-muted-foreground"
                      }`}
                    >
                      <Icon name={m.icon} size={11} strokeWidth={1.6} />
                      {m.label}
                    </button>
                  );
                })}
              </div>

              <div className="mt-4 flex gap-2">
                {editingId && (
                  <button
                    onClick={resetForm}
                    className="rounded-full border border-white/[0.08] px-4 py-3 text-[11px] uppercase tracking-[0.22em] text-muted-foreground"
                  >
                    Cancel
                  </button>
                )}
                <motion.button
                  whileTap={{ scale: 0.97 }}
                  onClick={save}
                  disabled={!label.trim()}
                  className="flex flex-1 items-center justify-center gap-2 rounded-full border border-white/20 bg-white/[0.06] py-3 text-[11px] uppercase tracking-[0.22em] text-foreground disabled:opacity-40"
                >
                  <Check size={14} strokeWidth={1.8} />
                  {editingId ? "Update" : "Save favorite"}
                </motion.button>
              </div>
            </div>
          </motion.div>

          <IconPicker
            open={pickerOpen}
            selected={icon}
            onSelect={setIcon}
            onClose={() => setPickerOpen(false)}
          />
        </>
      )}
    </AnimatePresence>
  );

  if (typeof document === "undefined") return null;
  return createPortal(node, document.body);
}

import { AnimatePresence, motion } from "framer-motion";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { Trash2, X, Pencil, Check } from "lucide-react";
import { Icon } from "./Icon";
import { CategoryPicker } from "./CategoryPicker";
import { IconPicker } from "./IconPicker";
import { useBodyScrollLock } from "@/hooks/useBodyScrollLock";
import { useKeyboardOffset } from "@/hooks/useKeyboardOffset";
import { useOverlayState } from "@/lib/OverlayContext";
import {
  PAYMENT_METHODS,
  PICKABLE_EXPENSE_CATEGORIES,
  PICKABLE_INCOME_CATEGORIES,
  type Direction,
  type Loop,
  type PaymentMethod,
} from "@/lib/ledger";
import { useCategoryColor } from "@/lib/themes";
import { showInfo } from "@/lib/undo";
import { haptic } from "@/lib/haptics";


interface Props {
  open: boolean;
  onClose: () => void;
  loops: Loop[];
  onAdd: (l: Omit<Loop, "id" | "lastAppliedDate">) => void;
  onUpdate: (id: string, l: Omit<Loop, "id" | "lastAppliedDate">) => void;
  onDelete: (id: string) => void;
  mode?: "manage" | "compact";
  initialEdit?: Loop | null;
}

export function LoopEditor({
  open, onClose, loops, onAdd, onUpdate, onDelete,
  mode = "manage", initialEdit = null,
}: Props) {
  useOverlayState(open);
  const themeColor = useCategoryColor();
  useBodyScrollLock(open);

  const [editingId, setEditingId] = useState<string | null>(null);
  const kb = useKeyboardOffset();
  const [label, setLabel] = useState("");
  const [icon, setIcon] = useState("Repeat");
  const [direction, setDirection] = useState<Direction>("out");
  const [category, setCategory] = useState(PICKABLE_EXPENSE_CATEGORIES[0].key);
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState<PaymentMethod>("upi");
  const [day, setDay] = useState<string>("1");
  const [pickerOpen, setPickerOpen] = useState(false);

  const resetForm = () => {
    setEditingId(null);
    setLabel(""); setIcon("Repeat"); setDirection("out");
    setCategory(PICKABLE_EXPENSE_CATEGORIES[0].key);
    setAmount(""); setMethod("upi"); setDay("1");
  };

  useEffect(() => {
    if (!open) { resetForm(); return; }
    if (initialEdit) {
      setEditingId(initialEdit.id);
      setLabel(initialEdit.label);
      setIcon(initialEdit.icon);
      setDirection(initialEdit.direction);
      setCategory(initialEdit.category);
      setAmount(String(initialEdit.amount));
      setMethod(initialEdit.paymentMethod);
      setDay(String(initialEdit.recurrenceDayOfMonth));
    } else {
      resetForm();
    }
  }, [open, initialEdit]);

  useEffect(() => {
    const pool = direction === "in" ? PICKABLE_INCOME_CATEGORIES : PICKABLE_EXPENSE_CATEGORIES;
    if (!pool.find((c) => c.key === category)) setCategory(pool[0].key);
  }, [direction, category]);

  const startEdit = (l: Loop) => {
    setEditingId(l.id);
    setLabel(l.label);
    setIcon(l.icon);
    setDirection(l.direction);
    setCategory(l.category);
    setAmount(String(l.amount));
    setMethod(l.paymentMethod);
    setDay(String(l.recurrenceDayOfMonth));
  };

  const save = () => {
    const amt = parseFloat(amount);
    const dayNum = parseInt(day, 10);
    if (!label.trim() || isNaN(amt) || amt <= 0 || isNaN(dayNum)) return;
    const payload: Omit<Loop, "id" | "lastAppliedDate"> = {
      label: label.trim(),
      icon, category, direction,
      amount: amt,
      paymentMethod: method,
      recurrenceDayOfMonth: Math.min(28, Math.max(1, dayNum)),
    };
    const wasEdit = !!editingId;
    if (editingId) onUpdate(editingId, payload);
    else onAdd(payload);
    haptic("success");
    resetForm();
    onClose();
    showInfo(wasEdit ? "Loop updated" : "Loop added");
  };


  const pool = direction === "in" ? PICKABLE_INCOME_CATEGORIES : PICKABLE_EXPENSE_CATEGORIES;

  const node = (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            className="fixed inset-0 z-40 bg-black/50"
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.div
            initial={{ y: "100%", opacity: 0 }} animate={{ y: kb ? -kb : 0, opacity: 1 }} exit={{ y: "100%", opacity: 0 }}
            transition={{ type: "spring", stiffness: 400, damping: 32, mass: 0.9 }}
            drag="y"
            dragConstraints={{ top: 0, bottom: 0 }}
            dragElastic={{ top: 0, bottom: 0.5 }}
            dragMomentum={false}
            onDragEnd={(event, info) => {
              if (info.offset.y > 100 || info.velocity.y > 500) {
                onClose();
              }
            }}
            className="fixed inset-x-0 bottom-0 z-50 mx-auto max-h-[92vh] w-full max-w-md overflow-x-hidden overflow-y-auto rounded-t-[32px] border-t border-white/10 bg-black p-5 pb-8"
            style={{
              background: "rgba(15, 15, 15, 0.65)",
              backdropFilter: "blur(10px) saturate(150%)",
              WebkitBackdropFilter: "blur(10px) saturate(150%)",
              borderColor: "rgba(255,255,255,0.08)",
              boxShadow: "inset 0 1px 0 rgba(255,255,255,0.08), 0 -20px 60px -20px rgba(0,0,0,0.8)",
            }}
          >
            <div className="mx-auto mb-4 h-1.5 w-12 rounded-full bg-white/15" />
            <div className="flex items-center justify-between">
              <div>
                <p className="text-[10px] uppercase tracking-[0.3em] text-muted-foreground">
                  {mode === "compact" ? (editingId ? "Edit" : "New") : "Manage"}
                </p>
                <h2 className="font-mono-display text-xl text-foreground/95">
                  {mode === "compact" ? "LOOP" : "LOOPS"}
                </h2>
              </div>
              <button onClick={onClose} className="rounded-full p-2 text-muted-foreground">
                <X size={18} strokeWidth={1.5} />
              </button>
            </div>

            {mode === "manage" && loops.length > 0 && (
              <div className="mt-5 space-y-1">
                <p className="mb-2 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">
                  Active · {loops.length}
                </p>
                {loops.map((l) => {
                  const isEditing = editingId === l.id;
                  return (
                    <motion.div
                      layout
                      key={l.id}
                      className={`flex items-center gap-3 rounded-2xl border px-3 py-2.5 transition-colors ${
                        isEditing
                          ? "border-white/20 bg-white/[0.06]"
                          : "border-white/[0.06] bg-white/[0.02]"
                      }`}
                    >
                      <span className="grid h-9 w-9 place-items-center rounded-xl border border-white/[0.08]">
                        <Icon name={l.icon} size={15} strokeWidth={1.5} />
                      </span>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-medium">{l.label}</p>
                        <p className="font-mono-display truncate text-[10px] uppercase tracking-[0.18em] text-muted-foreground">
                          {l.direction === "in" ? "+" : "−"}₹{l.amount} · day {l.recurrenceDayOfMonth}
                        </p>
                      </div>
                      <button
                        onClick={() => (isEditing ? resetForm() : startEdit(l))}
                        className="rounded-full p-2 text-muted-foreground active:opacity-60"
                        aria-label={isEditing ? "Cancel" : "Edit"}
                      >
                        {isEditing ? <X size={14} /> : <Pencil size={14} strokeWidth={1.6} />}
                      </button>
                      <button
                        onClick={() => { haptic("thud"); onDelete(l.id); }}
                        className="rounded-full p-2 text-muted-foreground active:opacity-60"
                        aria-label="Delete"
                      >
                        <Trash2 size={14} strokeWidth={1.6} />
                      </button>
                    </motion.div>
                  );
                })}
              </div>
            )}

            <div className="mt-5 rounded-2xl border border-white/[0.06] bg-white/[0.02] p-4">
              <p className="mb-3 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">
                {editingId ? "Editing loop" : "New loop"}
              </p>

              <div className="flex items-center gap-3">
                <button
                  onClick={() => setPickerOpen(true)}
                  className="grid h-14 w-14 shrink-0 place-items-center rounded-2xl border border-white/[0.08] bg-white/[0.03]"
                >
                  <Icon name={icon} size={22} strokeWidth={1.5} />
                </button>
                <input
                  value={label}
                  onChange={(e) => setLabel(e.target.value)}
                  placeholder="Label (e.g. Netflix)"
                  className="w-full border-b border-white/10 bg-transparent pb-1.5 text-base outline-none placeholder:text-muted-foreground focus:border-foreground/40"
                />
              </div>

              <div className="mt-4 flex gap-2">
                {(["out", "in"] as Direction[]).map((d) => (
                  <button
                    key={d}
                    onClick={() => setDirection(d)}
                    className={`flex-1 rounded-full border py-2 text-[10px] uppercase tracking-[0.22em] ${
                      direction === d
                        ? "border-white/30 bg-white/[0.05] text-foreground"
                        : "border-white/[0.06] text-muted-foreground"
                    }`}
                  >
                    {d === "in" ? "Income" : "Expense"}
                  </button>
                ))}
              </div>

              <CategoryPicker
                categories={pool}
                selectedKey={category}
                onSelect={(c) => { setCategory(c.key); setIcon(c.icon); }}
              />

              <div className="mt-4 grid grid-cols-2 gap-3">
                <div>
                  <p className="mb-1.5 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">Amount</p>
                  <div className="flex items-center gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2">
                    <span className="font-mono-display text-sm text-muted-foreground">₹</span>
                    <input
                      type="number" value={amount}
                      onChange={(e) => setAmount(e.target.value)}
                      placeholder="0"
                      className="font-mono-display w-full bg-transparent text-sm outline-none"
                    />
                  </div>
                </div>
                <div>
                  <p className="mb-1.5 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">Day of month</p>
                  <div className="flex items-center gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2">
                    <input
                      type="text"
                      inputMode="numeric"
                      pattern="[0-9]*"
                      value={day}
                      onChange={(e) => {
                        const v = e.target.value.replace(/[^0-9]/g, "");
                        setDay(v.slice(0, 2));
                      }}
                      placeholder="1–28"
                      className="font-mono-display w-full bg-transparent text-sm outline-none"
                    />
                  </div>
                </div>
              </div>

              <p className="mt-4 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">Payment method</p>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {PAYMENT_METHODS.map((m) => (
                  <button
                    key={m.key}
                    onClick={() => setMethod(m.key)}
                    className={`flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs ${
                      method === m.key
                        ? "border-white/30 bg-white/[0.06] text-foreground"
                        : "border-white/[0.06] text-muted-foreground"
                    }`}
                  >
                    <Icon name={m.icon} size={11} strokeWidth={1.6} /> {m.label}
                  </button>
                ))}
              </div>

              <div className="mt-4 flex gap-2">
                {editingId && (
                  <button
                    onClick={resetForm}
                    className="rounded-full border border-white/[0.08] px-4 py-3 text-[11px] uppercase tracking-[0.22em] text-muted-foreground"
                  >
                    Cancel
                  </button>
                )}
                <motion.button
                  whileTap={{ scale: 0.97 }}
                  onClick={save}
                  disabled={!label.trim() || !(parseFloat(amount) > 0)}
                  className="flex flex-1 items-center justify-center gap-2 rounded-full border border-white/20 bg-white/[0.06] py-3 text-[11px] uppercase tracking-[0.22em] text-foreground disabled:opacity-30"
                >
                  <Check size={14} strokeWidth={1.8} />
                  {editingId ? "Update" : "Save loop"}
                </motion.button>
              </div>
            </div>
          </motion.div>

          <IconPicker
            open={pickerOpen}
            selected={icon}
            onSelect={setIcon}
            onClose={() => setPickerOpen(false)}
          />
        </>
      )}
    </AnimatePresence>
  );

  if (typeof document === "undefined") return null;
  return createPortal(node, document.body);
}

