import { Icon } from "./Icon";
import type { CategoryDef } from "@/lib/ledger";

interface CategoryPickerProps {
  categories: CategoryDef[];
  selectedKey: string;
  onSelect: (category: CategoryDef) => void;
  recentKeys?: string[];
}

export function CategoryPicker({ categories, selectedKey, onSelect, recentKeys = [] }: CategoryPickerProps) {
  const recent = recentKeys
    .map((key) => categories.find((category) => category.key === key))
    .filter((category): category is CategoryDef => Boolean(category));

  return (
    <div className="space-y-3">
      {recent.length > 0 && (
        <div>
          <p className="mb-2 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">Recent</p>
          <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
            {recent.map((category) => (
              <CategoryButton key={`recent-${category.key}`} category={category} selected={category.key === selectedKey} onSelect={onSelect} compact />
            ))}
          </div>
        </div>
      )}
      <div>
        <p className="mb-2 text-[10px] uppercase tracking-[0.22em] text-muted-foreground">Category</p>
        <div className="grid grid-cols-3 gap-2">
          {categories.map((category) => (
            <CategoryButton key={category.key} category={category} selected={category.key === selectedKey} onSelect={onSelect} />
          ))}
        </div>
      </div>
    </div>
  );
}

function CategoryButton({ category, selected, onSelect, compact = false }: {
  category: CategoryDef;
  selected: boolean;
  onSelect: (category: CategoryDef) => void;
  compact?: boolean;
}) {
  return (
    <motion.button
      type="button"
      whileTap={{ scale: 0.96 }}
      onClick={() => onSelect(category)}
      className={`${compact ? "h-11 shrink-0 px-3" : "min-h-[68px] px-2 py-2"} flex items-center ${compact ? "gap-2 rounded-full" : "flex-col justify-center gap-1 rounded-2xl"} border text-center transition-colors`}
      style={{
        borderColor: selected ? category.color : "rgba(255,255,255,0.09)",
        background: selected ? `color-mix(in oklab, ${category.color} 18%, transparent)` : "rgba(255,255,255,0.025)",
        color: selected ? category.color : "rgba(255,255,255,0.72)",
        boxShadow: selected ? `0 0 0 1px color-mix(in oklab, ${category.color} 25%, transparent)` : "none",
      }}
    >
      <Icon name={category.icon} size={compact ? 14 : 18} strokeWidth={1.6} />
      <span className={`${compact ? "text-xs" : "max-w-full truncate text-[11px]"} font-medium`}>{category.label}</span>
    </motion.button>
  );
}
"}

